#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

# Power measurement capability (#7): does the Galaxy M34's fuel gauge show a
# plausible discharge current that rises under CPU load? The phone must be on
# battery, and an adb-shell script dies when the USB cable comes out, so the
# probe is started over Wireless debugging after the unplug.

export MSYS_NO_PATHCONV=1   # Git Bash: stop /data/... being rewritten as a Windows path
HERE=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
STATE="$HERE/.m34_original_settings"
ADB=$(command -v adb || echo "$HOME/AppData/Local/Android/Sdk/platform-tools/adb")
PROBE=/data/local/tmp/m34_probe.sh
PLOG=/data/local/tmp/m34_probe.log
CONNECT_HOSTPORT=""

adbu() { "$ADB" -d "$@" | tr -d '\r'; }
adbw() { "$ADB" -s "$CONNECT_HOSTPORT" "$@" | tr -d '\r'; }
winpath() { if command -v cygpath >/dev/null 2>&1; then cygpath -w "$1"; else printf '%s' "$1"; fi; }
phone_ip() { adbu shell ip -f inet addr show wlan0 2>/dev/null | awk '/inet /{print $2}' | cut -d/ -f1; }

[[ -x "$ADB" ]] || { warn "adb not found (looked on PATH and in the Android SDK)"; exit 1; }

banner "Galaxy M34: battery-current check under load"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Phone on USB"
say "Plug the Galaxy M34 into the laptop by USB and unlock it."
note "If an 'Allow USB debugging?' prompt appears, tick 'Always allow' and tap Allow."
pause "Press Enter once it's plugged in"
until [[ "$("$ADB" -d get-state 2>/dev/null | tr -d '\r')" == device ]]; do
  warn "no authorised USB phone yet. Check for the Allow prompt, or replug the cable."
  pause "Press Enter to check again"
done
MODEL=$(adbu shell getprop ro.product.model)
if [[ "$MODEL" == SM-M346B ]]; then
  say "Found the study phone: $MODEL (Galaxy M34 5G)."
else
  warn "this phone is $MODEL, not the study phone SM-M346B."
  confirm "Carry on anyway?" || exit 1
fi
if [[ -f "$STATE" ]]; then
  # shellcheck disable=SC1090
  source "$STATE"
  note "An earlier run was interrupted; I'll restore the settings it saved."
else
  ORIG_TIMEOUT=$(adbu shell settings get system screen_off_timeout)
  ORIG_WIFI=$(adbu shell settings get global wifi_on)
  printf 'ORIG_TIMEOUT=%s\nORIG_WIFI=%s\n' "$ORIG_TIMEOUT" "$ORIG_WIFI" > "$STATE"
fi
note "Saved to restore at the end: screen timeout ${ORIG_TIMEOUT} ms, Wi-Fi $([[ "$ORIG_WIFI" == 0 ]] && echo off || echo on)."
tmp=$(mktemp)
cat > "$tmp" <<'EOF'
#!/system/bin/sh
# idle 30 s / all 8 cores busy 45 s / idle 30 s, sampling the fuel gauge.
# Samsung reports current_now in mA; positive = charging, negative = discharging.
LOG=/data/local/tmp/m34_probe.log
echo "# start $(date +%T)" > $LOG
sample() { # $1 = phase, $2 = seconds
  end=$(( $(date +%s) + $2 ))
  while [ $(date +%s) -lt $end ]; do
    echo "$(date +%s.%N) $1 $(cmd battery get -f current_now) $(cmd battery get usb)" >> $LOG
    sleep 0.2
  done
}
echo "# voltage_before $(dumpsys battery | grep -m1 ' voltage:')" >> $LOG
sample idle_before 30
pids=""
for j in 1 2 3 4 5 6 7 8; do (while :; do :; done) & pids="$pids $!"; done
sample load 45
kill $pids
sample idle_after 30
echo "# voltage_after $(dumpsys battery | grep -m1 ' voltage:')" >> $LOG
echo "# done $(date +%T)" >> $LOG
EOF
"$ADB" -d push "$(winpath "$tmp")" "$PROBE" >/dev/null && adbu shell chmod 755 "$PROBE"
rm -f "$tmp"
printf '  %s✓ probe copied to the phone%s\n' "$GREEN" "$RESET"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Same network as the laptop"
adbu shell cmd wifi set-wifi-enabled enabled >/dev/null
say "Turned the phone's Wi-Fi on. Waiting for it to join a network..."
for _ in $(seq 1 20); do [[ -n "$(phone_ip)" ]] && break; sleep 1; done
PHONE_IP=$(phone_ip || true)
SSID=$(adbu shell cmd wifi status | grep -o 'connected to "[^"]*"' || true)
if [[ -n "$PHONE_IP" ]]; then say "Phone is on Wi-Fi: $PHONE_IP ${SSID:+($SSID)}"; else warn "the phone hasn't joined a Wi-Fi network yet."; fi
note "The laptop must be on the same network."
note "On 2026-10-19 the campus Wi-Fi (Amrita) let plain adb through but blocked Wireless debugging."
if confirm "Use the laptop's Mobile hotspot instead? (Recommended on campus Wi-Fi)"; then
  open_url "ms-settings:network-mobilehotspot"
  step "Turn Mobile hotspot On. Note its network name and password ('Properties' → 'Edit')."
  step "On the phone: Settings → Connections → Wi-Fi → join that network."
  pause "Press Enter once the phone has joined the hotspot"
  PHONE_IP=$(phone_ip || true)
  say "Phone is now at: ${PHONE_IP:-unknown}"
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Pair over Wireless debugging"
step "On the phone: Settings → Developer options → Wireless debugging → turn it On."
note "If it asks 'Allow wireless debugging on this network?', tap Allow."
step "Tap 'Pair device with pairing code' and keep that dialog open."
while :; do
  ask PAIR_HOSTPORT "IP address & port in the pairing dialog (e.g. ${PHONE_IP:-10.0.0.5}:37123):"
  ask PAIR_CODE "Wi-Fi pairing code (6 digits):"
  out=$(timeout 30 "$ADB" pair "$PAIR_HOSTPORT" "$PAIR_CODE" 2>&1 || true)
  if grep -qi "successfully paired" <<<"$out"; then
    printf '  %s✓ paired%s\n' "$GREEN" "$RESET"; break
  fi
  warn "pairing failed: ${out:-no answer within 30 s}"
  note "The code and port change each time the dialog opens; reopen it for fresh ones."
  note "No answer at all usually means the network blocks it; re-run and pick the Mobile hotspot."
  confirm "Try pairing again?" || exit 1
done
step "Close the pairing dialog. On the main Wireless debugging screen, read 'IP address & Port'."
while :; do
  ask CONNECT_HOSTPORT "IP address & port from the main Wireless debugging screen:"
  timeout 20 "$ADB" connect "$CONNECT_HOSTPORT" >/dev/null 2>&1 || true
  if [[ "$(adbw shell echo ok 2>/dev/null)" == ok ]]; then
    printf '  %s✓ connected over Wi-Fi%s\n' "$GREEN" "$RESET"; break
  fi
  warn "couldn't reach $CONNECT_HOSTPORT (this is a different port from the pairing one)."
  confirm "Try again?" || exit 1
done
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Unplug, screen on"
adbw shell settings put system screen_off_timeout 600000
adbw shell input keyevent KEYCODE_WAKEUP
note "Screen timeout is 10 minutes for now; it goes back to ${ORIG_TIMEOUT} ms at the end."
step "Unplug the USB cable."
step "Leave the screen ON. Don't press the power button: a locked phone suspends the probe."
step "Put the phone down face up and leave it alone until stage 6."
pause "Press Enter once it's unplugged"
while :; do
  if ! usb=$(adbw shell cmd battery get usb 2>/dev/null); then
    warn "lost the Wi-Fi connection when the cable came out. Reconnecting..."
    timeout 20 "$ADB" connect "$CONNECT_HOSTPORT" >/dev/null 2>&1 || true
    usb=$(adbw shell cmd battery get usb 2>/dev/null || echo unreachable)
  fi
  [[ "$usb" == false ]] && { printf '  %s✓ phone is on battery, still connected over Wi-Fi%s\n' "$GREEN" "$RESET"; break; }
  warn "phone reports USB power: '$usb'. Is the cable fully out?"
  confirm "Check again?" || exit 1
done
pause "Press Enter to start the probe (hands off from here)"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Probe running (about 2 minutes)"
say "Hands off the phone. The probe runs on the phone itself, so a Wi-Fi blip won't stop it."
adbw shell "setsid nohup sh $PROBE >/dev/null 2>&1 </dev/null &" || true
start=$(date +%s)
while :; do
  sleep 5
  elapsed=$(( $(date +%s) - start ))
  if [[ "$(adbw shell tail -n 1 "$PLOG" 2>/dev/null)" == "# done"* ]]; then printf '\n'; break; fi
  printf '\r  %s%3ss / ~110s%s ' "$DIM" "$elapsed" "$RESET"
  if (( elapsed > 300 )); then printf '\n'; warn "no '# done' after 5 minutes; pulling whatever was logged."; break; fi
done
printf '  %s✓ probe finished%s\n' "$GREEN" "$RESET"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Results"
LOG_OUT="$HERE/m34-discharge-$(date +%Y%m%d-%H%M%S).log"
adbw shell cat "$PLOG" > "$LOG_OUT" || { timeout 20 "$ADB" connect "$CONNECT_HOSTPORT" >/dev/null 2>&1; adbw shell cat "$PLOG" > "$LOG_OUT"; }
say "Raw log: $LOG_OUT"
awk '
  /voltage_before/ { for (i = 1; i <= NF; i++) if ($i == "voltage:") v = $(i+1) }
  /^#/ { next }
  { n[$2]++; s[$2] += $3; ss[$2] += $3 * $3; if ($4 != "false") plugged++ }
  END {
    split("idle_before load idle_after", ph, " ")
    for (k = 1; k <= 3; k++) { p = ph[k]; if (!n[p]) { print "  missing phase " p; bad = 1; continue }
      m[p] = s[p] / n[p]; sd[p] = sqrt(ss[p] / n[p] - m[p] * m[p])
      printf "  %-12s n=%3d  mean %7.1f mA  sd %6.1f  (~%5.0f mW)\n", p, n[p], m[p], sd[p], -m[p] * v / 1000 }
    if (bad) { print "  FAIL: a phase is missing, see the raw log"; exit }
    idle = (m["idle_before"] + m["idle_after"]) / 2; d = m["load"] - idle
    printf "\n  load minus idle: %.1f mA (~%.0f mW at %d mV)\n\n", d, -d * v / 1000, v
    ok = 1
    if (plugged) { print "  FAIL: " plugged " samples taken while on USB power"; ok = 0 }
    if (idle >= 0) { print "  FAIL: idle current is not negative, so the phone was not discharging"; ok = 0 }
    if (-d < 50) { print "  FAIL: load adds under 50 mA, so the gauge barely sees the CPU"; ok = 0 }
    for (k = 1; k <= 3; k += 2) if (m["load"] > m[ph[k]] - 2 * sd[ph[k]]) {
      print "  FAIL: load is within 2 sd of " ph[k]; ok = 0 }
    print ok ? "  PASS: the fuel gauge tracks CPU load while on battery." : "  Not a pass. Keep the raw log and post it on the ticket."
  }' "$LOG_OUT"
pause "Press Enter to put the phone back to normal"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Put the phone back"
adbw shell settings put system screen_off_timeout "$ORIG_TIMEOUT"
adbw shell rm -f "$PROBE" "$PLOG"
printf '  %s✓ screen timeout back to %s ms, probe removed%s\n' "$GREEN" "$ORIG_TIMEOUT" "$RESET"
# Turning Wireless debugging (and maybe Wi-Fi) off cuts this connection, so do it detached, last.
wifi_off=""; [[ "$ORIG_WIFI" == 0 ]] && wifi_off="; cmd wifi set-wifi-enabled disabled"
adbw shell "nohup sh -c 'sleep 2; settings put global adb_wifi_enabled 0$wifi_off' >/dev/null 2>&1 </dev/null &" || true
sleep 4
"$ADB" disconnect "$CONNECT_HOSTPORT" >/dev/null 2>&1 || true
rm -f "$STATE"
printf '  %s✓ Wireless debugging off%s%s\n' "$GREEN" "${wifi_off:+, Wi-Fi off again}" "$RESET"
SKIPPED+=("Check Developer options → Wireless debugging shows Off")
SKIPPED+=("If you used the laptop's Mobile hotspot, turn it off")
SKIPPED+=("Replug the phone and switch USB tethering back on if you use it")
SKIPPED+=("Tell Claude the result; the raw log is $LOG_OUT")
pause

finish
}

run_wizard "$@"; exit
